const event = msg.payload;
if (event.type !== 'message.received') {
    return null;
}
const data = event.data || {};
const sender = data.from || {};
if ((data.to && data.to.group_id) || !sender.number || data.content_type !== 'text') {
    return null;
}
const text = String(data.preview || '').toLowerCase();
if (!/\b(where|address|location)\b/.test(text)) {
    return null;
}
// Never more than 30 locations an hour in all, so a flood from many numbers cannot use up your message allowance.
const MAX_ALL = 30;
const nowMs = event.created_at ? new Date(event.created_at).getTime() : Date.now();
const lastHour = (flow.get('sentAll') || []).filter((t) => t > nowMs - 3600 * 1000);
if (lastHour.length >= MAX_ALL) {
    return null;
}
lastHour.push(nowMs);
flow.set('sentAll', lastHour);
// Never more than MAX_ANSWERS answers an hour to one person: two auto-responders cannot talk to each other forever.
const MAX_ANSWERS = 3;
const hourAgo = (event.created_at ? new Date(event.created_at).getTime() : Date.now()) - 3600 * 1000;
const sentTo = flow.get('sentTo') || {};
const recent = (sentTo[sender.number] || []).filter((t) => t > hourAgo);
if (recent.length >= MAX_ANSWERS) {
    return null;
}
recent.push(hourAgo + 3600 * 1000);
sentTo[sender.number] = recent;
flow.set('sentTo', sentTo);
msg.to = '+' + sender.number;
msg.number = event.number_alias || 'main';
msg.payload = '';
msg.location = {
    latitude: 51.5007,
    longitude: -0.1246,
    name: 'Our store',
    address: '10 Example Street, London',
};
return msg;
